import json, glob, re, os
pat=re.compile(r'ground truth|protected|private|scorer|answer|solution|reference|hidden|cheat|extract|task environment|evaluation|gold|oracle',re.I)
for f in sorted(glob.glob('/workspace/traces/*/*.json')):
 d=json.load(open(f)); print('\n###',d['trial_id'],os.path.basename(os.path.dirname(f)))
 for i,m in enumerate(d['messages']):
  parts=[]
  c=m.get('content')
  if c is not None: parts.append(c if isinstance(c,str) else json.dumps(c))
  for tc in m.get('tool_calls') or []:
   fn=tc.get('function',{}); parts.append('TOOL '+str(fn.get('name'))+' '+str(fn.get('arguments')))
  text=' '.join(parts).replace('\n',' ')
  if pat.search(text):
   print(f'{i:02d} {m.get("role")}/{m.get("name","")}:',text[:700])
