import json, glob, os, hashlib
for f in sorted(glob.glob('/workspace/traces/*/*.json')):
 d=json.load(open(f)); print('\n===== '+d['trial_id']+' '+os.path.basename(os.path.dirname(f))+' =====')
 for i,m in enumerate(d['messages']):
  r=m.get('role');
  if r=='assistant':
   if m.get('content'): print(f'{i:02d} assistant text: {str(m["content"])[:220].replace(chr(10)," ")}')
   for tc in m.get('tool_calls') or []:
    fn=tc.get('function',{}); name=fn.get('name'); raw=fn.get('arguments','')
    try: a=json.loads(raw)
    except: a={}
    detail=''
    if 'path' in a: detail=' path='+str(a['path'])
    elif name in ('terminal','exec_command'): detail=' cmd='+str(a.get('command') or a.get('cmd'))[:180].replace('\n',' ')
    elif name=='submit_answer': detail=' answer_sha='+hashlib.sha1(str(a.get('answer')).encode()).hexdigest()[:10]
    elif 'topology' in a: detail=' topology_sha='+hashlib.sha1(str(a['topology']).encode()).hexdigest()[:10]
    elif 'content' in a: detail=' content='+str(a['content'])[:180].replace('\n',' ')
    else: detail=' '+raw[:180].replace('\n',' ')
    print(f'{i:02d} assistant tool: {name}{detail}')
  elif r in ('system','user'):
   print(f'{i:02d} {r}: {str(m.get("content",""))[:220].replace(chr(10)," ")}')
  elif r=='tool':
   print(f'{i:02d} tool {m.get("name")}: {str(m.get("content",""))[:160].replace(chr(10)," ")}')
